package runtime

import (
	"os"
	"testing"

	"github.com/vmihailenco/msgpack/v5"
)

// These decode the same two checked-in files ferry-go's tests/fixture.rs
// decodes (testdata/ at the repo root, regenerated by
// `cargo run --example gen_fixtures -p ferry-go`). If the envelope's wire
// shape or version ever drifts between the two languages, one side's
// decode breaks here instead of silently misreading bytes at the bridge
// boundary.

type fixtureOut struct {
	Message string `msgpack:"message"`
}

func readFixture(t *testing.T, name string) []byte {
	t.Helper()
	data, err := os.ReadFile("../testdata/" + name)
	if err != nil {
		t.Fatalf("read fixture %q: %v", name, err)
	}
	return data
}

func TestOkFixtureDecodes(t *testing.T) {
	data := readFixture(t, "envelope_ok.msgpack")

	var envelope wireEnvelope
	if err := msgpack.Unmarshal(data, &envelope); err != nil {
		t.Fatalf("decode envelope: %v", err)
	}
	if envelope.Version != EnvelopeVersion {
		t.Fatalf("got version %d, want %d", envelope.Version, EnvelopeVersion)
	}
	if !envelope.Ok {
		t.Fatalf("got ok=false, want true")
	}

	var out fixtureOut
	if err := msgpack.Unmarshal(envelope.Payload, &out); err != nil {
		t.Fatalf("decode payload: %v", err)
	}
	if out.Message != "fixture" {
		t.Fatalf("got message %q, want %q", out.Message, "fixture")
	}
}

func TestErrFixtureDecodes(t *testing.T) {
	data := readFixture(t, "envelope_err.msgpack")

	var envelope wireEnvelope
	if err := msgpack.Unmarshal(data, &envelope); err != nil {
		t.Fatalf("decode envelope: %v", err)
	}
	if envelope.Version != EnvelopeVersion {
		t.Fatalf("got version %d, want %d", envelope.Version, EnvelopeVersion)
	}
	if envelope.Ok {
		t.Fatalf("got ok=true, want false")
	}

	var wireErr wireError
	if err := msgpack.Unmarshal(envelope.Payload, &wireErr); err != nil {
		t.Fatalf("decode error payload: %v", err)
	}
	if wireErr.Kind != KindGuest {
		t.Fatalf("got kind %q, want %q", wireErr.Kind, KindGuest)
	}
	if wireErr.Message != "fixture error" {
		t.Fatalf("got message %q, want %q", wireErr.Message, "fixture error")
	}
}
